mapper.insert:
insert into idempotency_request(
  actor_type, actor_id, operation, idempotency_key, request_hash, expires_at
) values (
  #{actorType}, #{actorId}, #{operation}, #{idempotencyKey}, #{requestHash}, #{expiresAt}
)
on conflict (actor_type, actor_id, operation, idempotency_key) do nothing

mapper.select:
select request_hash as "requestHash", response_body::text as "responseBody"
from idempotency_request
where actor_type = #{actorType}
  and actor_id = #{actorId}
  and operation = #{operation}
  and idempotency_key = #{idempotencyKey}

mapper.update:
update idempotency_request
set response_status = 200, response_body = cast(#{responseBody} as jsonb)
where actor_type = #{actorType}
  and actor_id = #{actorId}
  and operation = #{operation}
  and idempotency_key = #{idempotencyKey}

mapper.delete:
delete from idempotency_request
where actor_type = #{actorType}
  and actor_id = #{actorId}
  and operation = #{operation}
  and idempotency_key = #{idempotencyKey}
  and response_body is null
